/* OSOYOO Model No.2019012400 / UNO / Model X
 * code.txtを参考に、提供フローチャートの関数順・速度を実装。
 * 必須の配線変更: 右ENA D9→D5、サーボ信号 D5→D9。
 * ServoがTimer1を使うため、D9/D10でモーターPWMは使わない。
 * 同じフォルダのFlowchartLogic.hとBoardPins.hが必要。実機走行は未検証。
 */
#include <Arduino.h>
#define IR_USE_AVR_TIMER2
#include <IRremote.hpp>  // Arduino-IRremote 4.x
#include <Servo.h>
#include "FlowchartLogic.h"

#include "BoardPins.h"
constexpr uint16_t IR_ADVANCE=24,IR_BACK=82,IR_RIGHT=90,IR_LEFT=8,IR_STOP=28;
constexpr unsigned long REMOTE_TIMEOUT_MS=350;
constexpr unsigned long SENSOR_PERIOD_MS=60;

Servo headServo;
flowcar::Controller controller;
flowcar::Sensors sensors={flowcar::INVALID,false};
flowcar::Output drive={0,0,false,0};
flowcar::Remote RM=flowcar::STOP;
uint8_t M=0;                       // 車両状態（設計書参照）
uint32_t remoteAt=0,sequence=0,lastSensorAt=0;
bool remoteSeen=false,sensorSeen=false;
bool buzzerWasActive=false;
uint32_t buzzerStarted=0;
int8_t appliedRight=0,appliedLeft=0;

// リモコン状態: 未受信/STOP=0、上=1、下=2、右=3、左=4。
void do_IR_Tick() {
  if(!IrReceiver.decode()) return;
  const uint8_t flags=IrReceiver.decodedIRData.flags;
  const uint16_t key=IrReceiver.decodedIRData.command;
  if(flags & IRDATA_FLAGS_WAS_OVERFLOW) {
    remoteSeen=false;RM=flowcar::STOP;
  } else if(flags & IRDATA_FLAGS_IS_REPEAT) {
    if(remoteSeen) remoteAt=millis(); // リピートを新しい操作として扱わない
  } else {
    flowcar::Remote next=flowcar::STOP;bool known=true;
    switch(key) {
      case IR_ADVANCE:next=flowcar::FORWARD;break;
      case IR_BACK:next=flowcar::BACKWARD;break;
      case IR_RIGHT:next=flowcar::RIGHT;break;
      case IR_LEFT:next=flowcar::LEFT;break;
      case IR_STOP:next=flowcar::STOP;break;
      default:known=false;break;
    }
    if(known) {RM=next;remoteSeen=true;remoteAt=millis();++sequence;}
  }
  IrReceiver.resume();
}

// 超音波センサの状態: 5cm以下、5cm超15cm以下、安全、計測失敗。
unsigned long watch() {
  digitalWrite(Trig_PIN,LOW);delayMicroseconds(2);
  digitalWrite(Trig_PIN,HIGH);delayMicroseconds(10);
  digitalWrite(Trig_PIN,LOW);
  return pulseIn(Echo_PIN,HIGH,15000UL);
}
void updateUltrasonicState() { sensors.front=flowcar::classifyFront(watch()); }
// 左右いずれかLOWなら後方検知。Mへ直接代入せず車両状態で統合する。
void updateRearIRState() {
  sensors.rear=digitalRead(LFSensor_bl)==LOW||digitalRead(LFSensor_br)==LOW;
}
void updateVehicleState() {
  const uint32_t now=millis();
  const bool linkAlive=remoteSeen&&uint32_t(now-remoteAt)<=REMOTE_TIMEOUT_MS;
  drive=flowcar::update(controller,sensors,RM,linkAlive,sequence,now);
  M=drive.m;
}
// ブザー状態: 50ms ON/OFFを2回、600ms周期。delayで制御を止めない。
void warning() {
  const uint32_t now=millis();
  if(drive.buzzer&&!buzzerWasActive) buzzerStarted=now;
  buzzerWasActive=drive.buzzer;
  const uint32_t t=uint32_t(now-buzzerStarted)%600UL;
  const bool on=drive.buzzer&&(t<50UL||(t>=100UL&&t<150UL));
  digitalWrite(BUZZ_PIN,on?LOW:HIGH);
}
void setMotor(uint8_t in1,uint8_t in2,uint8_t pwm,int8_t percent) {
  digitalWrite(in1,percent>0?HIGH:LOW);
  digitalWrite(in2,percent<0?HIGH:LOW);
  const uint8_t magnitude=percent<0?-percent:percent;
  analogWrite(pwm,(uint16_t(magnitude)*255U+50U)/100U);
}
void stop_Stop() {
  analogWrite(speedPinR,0);analogWrite(speedPinL,0);
  digitalWrite(RightDirectPin1,LOW);digitalWrite(RightDirectPin2,LOW);
  digitalWrite(LeftDirectPin1,LOW);digitalWrite(LeftDirectPin2,LOW);
  appliedRight=0;appliedLeft=0;
}
void do_Drive_Tick() {
  if(drive.right==0&&drive.left==0) {stop_Stop();return;}
  // 出力方向が変わる場合は、先に左右のPWMを0にする。
  if((appliedRight>0&&drive.right<0)||(appliedRight<0&&drive.right>0)||
     (appliedLeft>0&&drive.left<0)||(appliedLeft<0&&drive.left>0)) stop_Stop();
  setMotor(RightDirectPin1,RightDirectPin2,speedPinR,drive.right);
  setMotor(LeftDirectPin1,LeftDirectPin2,speedPinL,drive.left);
  appliedRight=drive.right;appliedLeft=drive.left;
}
void setup() {
  const uint8_t outputs[]={RightDirectPin1,RightDirectPin2,speedPinR,
      LeftDirectPin1,LeftDirectPin2,speedPinL,BUZZ_PIN,Trig_PIN};
  for(uint8_t pin:outputs) pinMode(pin,OUTPUT);
  stop_Stop();digitalWrite(BUZZ_PIN,HIGH);digitalWrite(Trig_PIN,LOW);
  pinMode(LFSensor_bl,INPUT);pinMode(LFSensor_br,INPUT);pinMode(Echo_PIN,INPUT);
  headServo.attach(SERVO_PIN);headServo.write(90);
  delay(400); // 起動時の正面合わせだけ。モーター停止中。
  IrReceiver.begin(IR_RECEIVE_PIN,DISABLE_LED_FEEDBACK);
}
void loop() {
  do_IR_Tick();                                      // 1. リモコン状態
  const uint32_t now=millis();
  if(!sensorSeen||uint32_t(now-lastSensorAt)>=SENSOR_PERIOD_MS) {
    updateUltrasonicState();                         // 2. 超音波センサ状態
    sensorSeen=true;lastSensorAt=now;
  }
  updateRearIRState();                               // 3. 赤外線センサ状態
  do_IR_Tick(); // pulseIn待機中に届いたSTOPを、出力前にも取り込む
  updateVehicleState();                              // 4. 車両状態
  warning();                                         // 5. ブザー状態
  do_Drive_Tick();                                    // 6. 行動状態
}

#ifndef FLOWCHART_LOGIC_H
#define FLOWCHART_LOGIC_H
#include <stdint.h>
namespace flowcar {
// RMは原図の値。右=3、左=4。
enum Remote : uint8_t { STOP=0, FORWARD=1, BACKWARD=2, RIGHT=3, LEFT=4 };
enum Front : uint8_t { CLEAR, CAUTION, EMERGENCY, INVALID };
enum Phase : uint8_t { MANUAL, BRAKING, ESCAPING, WAIT_NEW };
struct Sensors { Front front; bool rear; };
struct Output { int8_t right; int8_t left; bool buzzer; uint8_t m; };
struct Controller {
  Phase phase=WAIT_NEW;
  uint32_t started=0;
  uint32_t lastSequence=0;
  bool escapeBackward=false;
};
inline Front classifyFront(unsigned long echoUs) {
  if(echoUs==0) return INVALID;
  // 元コードと同じ換算係数0.01657。丸める前の距離で境界判定。
  const float cm=echoUs*0.01657f;
  if(cm<=5.0f) return EMERGENCY;
  if(cm<=15.0f) return CAUTION;
  return CLEAR;
}
inline Output stop(bool alarm=false,uint8_t m=0) { return {0,0,alarm,m}; }
inline Output manual(Remote rm) {
  switch(rm) {
    case FORWARD: return {50,50,false,3};
    case BACKWARD: return {-30,-30,false,4};
    case LEFT: return {30,-30,false,5};
    case RIGHT: return {-30,30,false,6};
    default: return stop();
  }
}
// 非ブロッキングの停止→反対方向10%→停止。回避完了後は新しい操作待ち。
inline Output update(Controller& c,Sensors s,Remote rm,bool linkAlive,
                     uint32_t sequence,uint32_t now) {
  const bool fresh=sequence!=c.lastSequence;
  c.lastSequence=sequence;
  const bool frontBlocked=s.front==CAUTION||s.front==EMERGENCY;
  const bool alarm=s.front==INVALID||frontBlocked||s.rear;
  if(!linkAlive||rm==STOP) { c.phase=WAIT_NEW;return stop(alarm); }
  if(s.front==INVALID) { c.phase=WAIT_NEW;return stop(true,8); }
  if(s.front==EMERGENCY) { c.phase=WAIT_NEW;return stop(true,1); }
  if(frontBlocked&&s.rear) { c.phase=WAIT_NEW;return stop(true,7); }
  if(c.phase==WAIT_NEW) {
    if(!fresh) return stop(alarm);
    c.phase=MANUAL;
  }
  if(c.phase==BRAKING||c.phase==ESCAPING) {
    // 回避方向も毎ループ監視。前後同時・5cm以下は上で停止する。
    const bool obstacleRemains=c.escapeBackward?frontBlocked:s.rear;
    if(!obstacleRemains) { c.phase=WAIT_NEW;return stop(alarm); }
    if(uint32_t(now-c.started)>=1500U) { c.phase=WAIT_NEW;return stop(true); }
    if(c.phase==BRAKING) {
      if(uint32_t(now-c.started)<100U) return stop(true,c.escapeBackward?1:2);
      c.phase=ESCAPING;
    }
    return c.escapeBackward?Output{-10,-10,true,1}:Output{10,10,true,2};
  }
  // 原図の「前方→後方→リモコン」の優先順。起動直後やSTOP中は自走しない。
  if(frontBlocked||s.rear) {
    c.escapeBackward=frontBlocked;
    c.started=now;c.phase=BRAKING;
    return stop(true,frontBlocked?1:2);
  }
  return manual(rm);
}
}
#endif

#ifndef FLOWCHART_BOARD_PINS_H
#define FLOWCHART_BOARD_PINS_H
#include <Arduino.h>
// ２.jpg / 4.jpg / 配線.jpg / 6.jpg / 3.jpg / 7.png を照合。
// false: 前版と同じ。true: 配線.jpgのEcho D2を採用し、右後方信号はA5へ移す。
// 切り替える場合はEchoと右後方センサーの実配線も変更する。
constexpr bool USE_PHOTO_ECHO_WIRING=false;
constexpr uint8_t IR_RECEIVE_PIN=4;
constexpr uint8_t speedPinR=5;       // 元code.txtの9から変更（ENAの線を移す）
constexpr uint8_t RightDirectPin1=12;
constexpr uint8_t RightDirectPin2=11;
constexpr uint8_t speedPinL=6;
constexpr uint8_t LeftDirectPin1=7;
constexpr uint8_t LeftDirectPin2=8;
constexpr uint8_t BUZZ_PIN=13;       // LOWで鳴動するアクティブブザー
constexpr uint8_t LFSensor_bl=0;     // code.txtを継承。D0のためSerialは使わない
constexpr uint8_t LFSensor_br=USE_PHOTO_ECHO_WIRING?A5:2;
constexpr uint8_t Echo_PIN=USE_PHOTO_ECHO_WIRING?2:3; // 画像はD2、code.txtはD3
constexpr uint8_t Trig_PIN=10;
constexpr uint8_t SERVO_PIN=9;       // 元code.txtの5から変更（サーボの信号線を移す）

namespace wiringcheck {
constexpr bool contains(int) {return false;}
template<typename... Rest> constexpr bool contains(int pin,int next,Rest... rest) {
  return pin==next||contains(pin,rest...);
}
constexpr bool unique() {return true;}
template<typename... Rest> constexpr bool unique(int pin,Rest... rest) {
  return !contains(pin,rest...)&&unique(rest...);
}
}
static_assert(wiringcheck::unique(IR_RECEIVE_PIN,speedPinR,RightDirectPin1,
 RightDirectPin2,speedPinL,LeftDirectPin1,LeftDirectPin2,BUZZ_PIN,
 LFSensor_bl,LFSensor_br,Echo_PIN,Trig_PIN,SERVO_PIN),"Pin collision: check BoardPins.h and wiring");
// Servo=Timer1、IRremote=Timer2のためモーターPWMはTimer0のD5/D6を使用。
static_assert((speedPinR==5||speedPinR==6)&&(speedPinL==5||speedPinL==6),
 "UNO motor PWM must use D5/D6 with Servo and Timer2 IRremote");
#endif

/* 5.jpgのOSOYOO 5-Channel IR Tracker専用の読み取り診断。
 * 画像の配線: IR1=A0, IR2=A1, IR3=A2, IR4=A3, IR5=A4。
 * 車両の前進・後退は行わない。値をSerial Monitor 115200bpsへ出す。
 * D0へ後方センサーを接続している場合、電源を切って信号線を外してから使う。
 * 各チャンネルの0/1をそのまま表示し、後方障害物としては判定しない。
 */
#include <Arduino.h>
constexpr uint8_t TRACKER_PINS[]={A0,A1,A2,A3,A4};
uint32_t previous=0;
void setup() {
  // 改訂版ENA D5 / ENB D6、Model Xの方向線を停止へ。
  pinMode(5,OUTPUT);pinMode(6,OUTPUT);analogWrite(5,0);analogWrite(6,0);
  const uint8_t directions[]={12,11,7,8};
  for(uint8_t pin:directions) {pinMode(pin,OUTPUT);digitalWrite(pin,LOW);}
  pinMode(13,OUTPUT);digitalWrite(13,HIGH);
  for(uint8_t pin:TRACKER_PINS) pinMode(pin,INPUT);
  Serial.begin(115200);
  Serial.println(F("IR1(A0),IR2(A1),IR3(A2),IR4(A3),IR5(A4) / raw 0=LOW 1=HIGH"));
}
void loop() {
  const uint32_t now=millis();
  if(uint32_t(now-previous)<200U) return;
  previous=now;
  for(uint8_t i=0;i<5;++i) {
    if(i) Serial.print(',');
    Serial.print(digitalRead(TRACKER_PINS[i]));
  }
  Serial.println();
}
